#!/usr/bin/env bash
# generated by `kit setup` — do not edit; re-run kit setup
# kit v5 global git hook shim (__HOOK__): the global core.hooksPath points at this
# directory, so git runs these shims for EVERY repo on the machine (design §7.1).
#   pre-commit / pre-push: run the kit guard ($kit_root/plugin/guard/<hook>.sh),
#     fail-loud when it cannot be found (design §7.5), then chain to the repo's hook.
#   every other hook: chain only — a global hooksPath would otherwise silently
#     switch off repo-local hooks (git-lfs, commit-msg linters, …).
# The repo-local hook is found via `git rev-parse --git-common-dir` (absolute;
# worktrees share the main repo's hooks). NEVER `--git-path hooks`: it honours
# core.hooksPath, resolves back to this shim and recurses forever (Phase 0 spike).
# A repo-local core.hooksPath (husky-style) overrides the global one and this shim
# never runs there — `kit doctor` / `kit guard status` / `kit audit` (A16) flag it.
#   post-checkout / post-merge / post-rewrite / post-commit: also keep the repo's
#     local-only files (PROJECT.toml, docs/LESSONS.md, plans, .claude/) safe across
#     checkouts of pre-migration commits ($kit_root/plugin/guard/localfiles.sh; best
#     effort, never changes the hook's exit status).
# Runs as `bash -p` (review R5-1): no shell functions imported from the environment (an
# exported `cat` / `bash` / `git` function would blind or skip the guard) and no $BASH_ENV
# for everything after this line; "$BASH" is the running bash by absolute path (no lookup).
case $- in *p*) ;; *) exec "$BASH" -p "${BASH_SOURCE[0]}" "$@" ;; esac
HOOK="__HOOK__"
SELF="${BASH_SOURCE[0]}"
CFG_DIR="$(cd "$(dirname "$SELF")/.." 2>/dev/null && pwd)"
CFG="$CFG_DIR/config.toml"
INPUT=""
case "$HOOK" in
    post-checkout|post-merge|post-rewrite|post-commit)
        KIT_ROOT="$(sed -nE '/^[[:space:]]*\[/q; s/^[[:space:]]*kit_root[[:space:]]*=[[:space:]]*"([^"]*)".*/\1/p' "$CFG" 2>/dev/null | head -n 1)"
        LF="$KIT_ROOT/plugin/guard/localfiles.sh"
        [[ -n "$KIT_ROOT" && -f "$LF" ]] && "$BASH" -p "$LF" "$HOOK" "$@" </dev/null || true
        ;;
    pre-commit|pre-push)
        KIT_ROOT="$(sed -nE '/^[[:space:]]*\[/q; s/^[[:space:]]*kit_root[[:space:]]*=[[:space:]]*"([^"]*)".*/\1/p' "$CFG" 2>/dev/null | head -n 1)"
        GUARD="$KIT_ROOT/plugin/guard/$HOOK.sh"
        if [[ -z "$KIT_ROOT" || ! -f "$GUARD" ]]; then
            echo "KIT GUARD: not configured (config: $CFG, guard: ${GUARD}) — run: kit setup   (to remove the global hook instead: kit setup --uninstall)" >&2
            exit 1
        fi
        # pin the config dir to this shim's own location: an inherited
        # KIT_CONFIG_HOME cannot point the guard at an empty privacy list
        export KIT_GUARD_CONFIG_DIR="$CFG_DIR"
        if [[ "$HOOK" == pre-push ]]; then
            INPUT="$(cat; echo .)"; INPUT="${INPUT%.}"     # keep stdin byte-exact for both readers
            printf '%s' "$INPUT" | "$BASH" -p "$GUARD" "$@" || exit $?
        else
            "$BASH" -p "$GUARD" "$@" || exit $?
        fi
        ;;
esac
GCD="$(git rev-parse --path-format=absolute --git-common-dir 2>/dev/null || git rev-parse --git-common-dir 2>/dev/null)"
LOCAL="${GCD:+$GCD/hooks/$HOOK}"
if [[ -n "$LOCAL" && -f "$LOCAL" && -x "$LOCAL" && ! "$LOCAL" -ef "$SELF" ]]; then
    if [[ "$HOOK" == pre-push ]]; then
        printf '%s' "$INPUT" | "$LOCAL" "$@"
        exit $?
    fi
    exec "$LOCAL" "$@"
fi
exit 0
